head.script:
// 테스트 설명, 유효성 값 설정
// 동작 조건(interactionMode) / submission 무시 / 함수 파라미터 / interactionEnterKey 별 실행 시점 / 직전 검색어 / 미설정 시 false 동작 검증 담당
// (_2 는 사용자 정의 함수의 반환값 미사용·실행 결과 반영(setItemSet·openTable) 담당)
scwin.tData = {
    "description" : "[autoComplete > P > submissionFunc]<br/>interactionMode='true' 일때 아이템을 동적으로 생성할 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "interactionMode='true' 일때 동작합니다.",
        "submissionFunc 속성 설정 시 submission 속성은 무시됩니다.",
        "사용자 정의 함수의 파라미터로 입력값과 검색을 실행한 키의 keyCode 값이 전달됩니다.",
        "interactionEnterKey 속성값에 따라 다음의 경우에 사용자 정의 함수가 실행됩니다. interactionEnterKey='false' : 사용자가 값을 입력하거나 아이템 리스트창이 닫힌 상태에서 아래 화살표키를 누르면 실행됩니다.",
        "interactionEnterKey 속성값에 따라 다음의 경우에 사용자 정의 함수가 실행됩니다. interactionEnterKey='true' : Enter 키를 누르면 실행됩니다.(사용자가 값을 입력하는 경우엔 실행되지 않습니다.)",
        "사용자의 입력값이 직전에 실행한 검색어와 같으면 사용자 정의 함수가 다시 실행되지 않습니다.",
        "submission, submissionFunc 속성을 모두 설정하지 않으면 interactionMode='false' 로 동작합니다."
    ]
}

// 컴포넌트에 설정된 아이템 겸 검색 대상 데이터
scwin.arrCity = [
    { "label" : "Seoul", "value" : "SEL" },
    { "label" : "Seongnam", "value" : "SNM" },
    { "label" : "Busan", "value" : "PUS" },
    { "label" : "Jeju", "value" : "CJU" }
];

scwin.gVar = {
    "arrRequest" : [],   // 아이템 데이터 요청 기록 (확인 버튼 클릭 시 출력 후 비움)
    "arrItem" : [],      // 확인 버튼 mousedown 시점의 리스트창 표시 아이템
    "isOpen" : false,    // 확인 버튼 mousedown 시점의 리스트창 표시 여부
    "itemCount" : 0      // 확인 버튼 mousedown 시점의 아이템 개수
};



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 컴포넌트 아이템 DataList / 검색 결과 DataList 생성
    let arrDltId = ["dlt_city", "dlt_result"];
    arrDltId.forEach(function (dltId) {
        let strDlt = '';
        strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="' + dltId + '">';
        strDlt += '<w2:columnInfo>';
        strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
        strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
        strDlt += '</w2:columnInfo>';
        strDlt += '</w2:dataList>';
        $p.data.create(strDlt);
    });
    dlt_city.setJSON(scwin.arrCity);

    // con 기본값 : interactionMode=true, interactionEnterKey=true, submission=sbm_search(Scope 적용 ID), submissionFunc=scwin.searchItem
    con_interactionMode.setValue("2");
    con_interactionEnterKey.setValue("2");
    con_submission.setSelectedIndex(1);
    con_submissionFunc.setSelectedIndex(1);

    // 확인 버튼을 누르면 편집 모드가 해제되어 리스트창이 먼저 닫히므로 mousedown capture 단계에서 리스트창 상태를 기록
    btn_getRequest.render.addEventListener("mousedown", scwin.captureListState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') target1.remove();

    $c.gcm.createLabel('label="[전제]\n- 컴포넌트 아이템 : Seoul, Seongnam, Busan, Jeju\n- 요청이 실행되면 검색어를 포함하는 아이템으로 setItemSet 후 openTable 호출(submission 은 정적 파일 응답 완료 후 key 노드값으로 처리)\n- submission 옵션은 Scope 적용 ID(mf_sbm_search)로 설정\n- 직전 검색어와 같으면 다시 요청하지 않으므로 절차마다 Target 재생성 후 시작\n- 확인 클릭은 편집 모드를 해제하므로 절차 마지막에만 클릭\n[절차]\n1. 입력창 클릭 -> Se 입력 -> 확인\n2. interactionEnterKey=true : 입력창 클릭 -> Se 입력 -> Enter -> Enter -> 확인\n3. interactionEnterKey=false : 입력창 클릭 -> Se 입력 -> 목록에서 Seoul 클릭 -> 입력창 클릭 -> 아래 화살표키 -> 확인\n[확인] 요청 기록(keyCode : 13=Enter, 40=아래 화살표키, 그 외=입력 문자), 확인 직전 아이템 개수와 리스트창 아이템"', '', 'label1');

    scwin.gVar.arrRequest = [];
    scwin.gVar.arrItem = [];
    scwin.gVar.isOpen = false;
    scwin.gVar.itemCount = 0;
    dlt_result.removeAll();

    let properties = {
        interactionMode : con_interactionMode.getText(),
        interactionEnterKey : con_interactionEnterKey.getText(),
        keyInputRef : "req/search",
        // submission 속성의 정의 ID(sbm_search)는 화면 Scope 에서 찾지 못하므로(결함 후보 대기 목록 기재) Scope 적용 ID 로 설정
        submission : (con_submission.getValue() === "scope" ? $p.getSubmission("sbm_search").id : ""),
        submissionFunc : con_submissionFunc.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
}



// 검색어를 포함하는 아이템을 결과 DataList 에 담고 setItemSet 으로 아이템 설정 후 openTable 로 리스트창 표시
scwin.applyResult = function (searchStr) {
    let arrResult = scwin.arrCity.filter(function (item) {
        return item.label.indexOf(searchStr) > -1;
    });
    dlt_result.setJSON(arrResult);
    target1.setItemSet("data:dlt_result", "label", "value");
    target1.openTable();
};



// submissionFunc 방식 : 입력값·keyCode 기록 후 결과 반영
scwin.searchItem = function (searchStr, keyCode) {
    scwin.gVar.arrRequest.push("submissionFunc 호출(" + (searchStr === "" ? "(빈 문자열)" : searchStr) + ", " + keyCode + ")");
    scwin.applyResult(searchStr);
};



// submission 방식 : 실행 직전 keyInputRef 경로 아래 key 노드값 기록
scwin.sbm_search_submit = function (e) {
    scwin.gVar.arrRequest.push("submission 실행(key = " + WebSquare.ModelUtil.getInstanceValue("req/search/key") + ")");
};



// submission 완료 : key 노드값으로 결과 반영 (응답 파일 내용은 사용하지 않음)
scwin.sbm_search_submitdone = function (e) {
    scwin.applyResult(WebSquare.ModelUtil.getInstanceValue("req/search/key"));
};



// 확인 버튼 mousedown 시점(리스트창이 닫히기 전)의 아이템 개수, 리스트창 표시 여부와 표시 아이템 기록
scwin.captureListState = function (e) {
    scwin.gVar.arrItem = [];
    scwin.gVar.isOpen = false;
    scwin.gVar.itemCount = target1.getItemCount();

    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    if (!itemTableElem) {
        return;
    }
    let objStyle = getComputedStyle(itemTableElem);
    if (objStyle.display === "none" || objStyle.visibility === "hidden") {
        return;
    }
    scwin.gVar.isOpen = true;

    // 숨겨진 Row 는 제외하고 화면에 보이는 아이템만 수집
    let rowList = itemTableElem.querySelectorAll("[id='" + target1.id + "_itemTable_main'] tr");
    for (let i = 0; i < rowList.length; i++) {
        if (rowList[i].offsetHeight > 0) {
            scwin.gVar.arrItem.push(rowList[i].textContent.trim());
        }
    }
};



// 직전 확인 이후의 요청 기록(검색어·keyCode)과 아이템 개수·리스트창 아이템 출력 후 요청 기록 비움 (validation 1 ~ 7)
scwin.btn_getRequest_onclick = function (e) {
    let strResult = "요청 : " + (scwin.gVar.arrRequest.length > 0 ? scwin.gVar.arrRequest.join(" / ") : "없음");
    strResult += " / 아이템 개수 : " + scwin.gVar.itemCount;
    strResult += " / 리스트창 : " + (scwin.gVar.isOpen ? scwin.gVar.arrItem.join(", ") : "닫힘");
    wf_body_bottom.getObj("scwin").setReturnValue(strResult);
    scwin.gVar.arrRequest = [];
};
